  unitChanged() {

    SharedIonic.loading(this.loadingController);

    if (this.unit === 'lbs') {

      if (this.lastUnit === 'cfm') {

        this.VE = [...this.lbs];
        this.calcMinMax();
        this.lastUnit = 'lbs';
      } else {

        this.VE = [...this.lbs];
        this.calcMinMax();
        this.lastUnit = 'lbs';
      }

    } else if (this.unit === 'cfm') {

      if (this.lastUnit === 'lbs') {

        // this.convert0(0.069);
        this.VE = [...this.cfm];
        this.calcMinMax();
        this.lastUnit = 'cfm';
      } else {

        // this.convert0(0.069);
        this.VE = [...this.cfm];
        this.calcMinMax();
        this.lastUnit = 'cfm';
      }

    } else {

      if (this.lastUnit === 'lbs') {

        // this.convert4(132);
        this.VE = [...this.kg];
        this.calcMinMax();
        this.lastUnit = 'kg';
      } else {

        // this.convert3(9.108);
        this.VE = [...this.kg];
        this.calcMinMax();
        this.lastUnit = 'kg';
      }
    }

    SharedIonic.dismissLoading(this.loadingController);
  }

  onCFM() {

    SharedIonic.loading(this.loadingController);
    const displacement = ((this.form.value.engineVolum / 1000) * 61);
    const c = this.form.value.engineVolum * 0.061023744095;
    const temp = this.form.value.temp * 1.8 + 32;
    const x = (-0.0002 * this.form.value.temp) + 0.0801;

    for (let i = 1; i < this.VE.length; i++) {

      const m = +(this.VE[i][0] * 0.145).toFixed(1);
      this.VE[i][0] = m;
      this.lbs[i][0] = m;
      this.cfm[i][0] = m;
      this.kg[i][0] = m;

      for (let j = 0; j < this.VE[i].length; j++) {

        if (j != 0) {

          const ve = this.VE[i][j];
          const rpm = this.VE[0][j];

          const res = Math.round(ve * rpm * c / 345600);

          this.VE[i][j] = +(res * x).toFixed(2);
          this.cfm[i][j] = res;
          this.lbs[i][j] = +(res * x).toFixed(2);
          this.kg[i][j] = +(res * x / 132.3).toFixed(3);

          //const res = +((ve * 0.01 * rpm / 2 * c * (m + this.form.value.boost)) / (this.r * (460 + temp))).toFixed(1);

          // this.VE[i][j] = res;
          // this.lbs[i][j] = res;
          // this.cfm[i][j] = +(res / x).toFixed(0);
          // this.kg[i][j] = +(res / 132.3).toFixed(3);
        }
      }
    }

    if (this.unit === 'lbs') {

      this.VE = [...this.lbs];

    } else if (this.unit === 'cfm') {

      this.VE = [...this.cfm];

    } else {

      this.VE = [...this.kg];
    }

    SharedIonic.dismissLoading(this.loadingController);
    this.veMode = false;
  }

